def age = 28

// If-else ladder for age categories
if (age < 13) {
    log.info("You are a child.")
} else if (age >= 13 && age <= 19) {
    log.info("You are a teenager.")
} else if (age >= 20 && age <= 29) {
    log.info("You are a young adult.")
} else if (age >= 30 && age <= 59) {
    log.info("You are an adult.")
} 

else {
    log.info("You are a senior learner.")
}


4. Loop with log.info =========




// Find least value in an array (Groovy)

// Example array
def arr = [10, 3, 7, 1, 9]

if (arr == null || arr.isEmpty()) {
    log.warn("Array khali hai — minimum value nahi milega.")
} 


else
 {
    // 1) Built-in simple way
    def least = arr.min()
    log.info("Least value (using min): ${least}")

    // 2) Manual way (loop) — useful jab custom comparison chahiye ho
    def leastManual = arr[0] # 10
    arr.each { v ->
        if (v < leastManual) {
            leastManual = v
        }
    }
    log.info("Least value (manual): ${leastManual}")
}


// Utility: find minimum in a list (returns null and logs if list is null/empty)
def findMin(List arr) {
    if (arr == null || arr.isEmpty()) {
        log.warn("Array khali hai — minimum value nahi milega.")
        return null
    }
    return arr.min()
}

// Manual implementation (useful for custom logic)
def findMinManual(List arr) {
    if (arr == null || arr.isEmpty()) {
        log.warn("Array khali hai — minimum value nahi milega.")
        return null
    }
    def minVal = arr[0]
    arr.each { v -> if (v < minVal) minVal = v }
    return minVal
}

// Usage example
def sample = [10, 3, 7, 1, 9]
def least = findMin(sample)
log.info("Least value (findMin): ${least}")

def least2 = findMinManual(sample)
log.info("Least value (findMinManual): ${least2}")
